import React from 'react';
import { CityGraph, TrafficLevel } from '../types';

interface Props {
  graph: CityGraph;
  highlightPath: string[];
}

const trafficColors: Record<TrafficLevel, string> = {
  Low: '#10b981',
  Moderate: '#f59e0b',
  Heavy: '#ef4444',
  Blocked: '#6b7280',
};

const GraphVisualization: React.FC<Props> = ({ graph, highlightPath }) => {
  const getNodeColor = (type: string) => {
    switch(type) {
      case 'Ambulance': return '#6366f1';
      case 'Patient': return '#f59e0b';
      case 'Hospital': return '#10b981';
      default: return '#475569';
    }
  };

  const isEdgeInPath = (from: string, to: string) => {
    for (let i = 0; i < highlightPath.length - 1; i++) {
      if (
        (highlightPath[i] === from && highlightPath[i + 1] === to) ||
        (highlightPath[i] === to && highlightPath[i + 1] === from)
      ) {
        return true;
      }
    }
    return false;
  };

  return (
    <svg width="100%" height="400" viewBox="0 0 1000 600" style={{ background: 'rgba(15, 23, 42, 0.5)', borderRadius: '16px', border: '1px solid rgba(255,255,255,0.08)' }}>
      {/* Edges */}
      {graph.edges.map((edge, idx) => {
        const fromNode = graph.nodes.find(n => n.id === edge.from)!;
        const toNode = graph.nodes.find(n => n.id === edge.to)!;
        const inPath = isEdgeInPath(edge.from, edge.to);

        return (
          <line
            key={idx}
            x1={fromNode.x}
            y1={fromNode.y}
            x2={toNode.x}
            y2={toNode.y}
            stroke={inPath ? '#6366f1' : trafficColors[edge.traffic]}
            strokeWidth={inPath ? 6 : 2}
            strokeDasharray={edge.traffic === 'Blocked' ? '6,6' : '0'}
            strokeLinecap="round"
            style={{
              transition: 'all 0.3s ease',
              filter: inPath ? 'drop-shadow(0 0 6px rgba(99, 102, 241, 0.5))' : 'none',
              opacity: inPath ? 1 : 0.6
            }}
          />
        );
      })}
      {/* Nodes */}
      {graph.nodes.map(node => (
        <g key={node.id}>
          <circle
            cx={node.x}
            cy={node.y}
            r={24}
            fill={getNodeColor(node.type)}
            style={{
              filter: 'drop-shadow(0 2px 8px rgba(0,0,0,0.3))',
              transition: 'all 0.3s ease'
            }}
          />
          <circle
            cx={node.x}
            cy={node.y}
            r={20}
            fill="none"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth="2"
          />
          <text x={node.x} y={node.y + 5} textAnchor="middle" fill="white" fontSize="14" fontWeight="600" fontFamily="Inter">
            {node.id}
          </text>
          <text x={node.x} y={node.y + 42} textAnchor="middle" fill="#94a3b8" fontSize="12" fontWeight="500" fontFamily="Inter">
            {node.name}
          </text>
        </g>
      ))}
      {/* Legend */}
      <g transform="translate(20, 20)">
        <rect x="0" y="0" width="150" height="120" fill="rgba(15, 23, 42, 0.9)" rx="8" opacity="0.95" stroke="rgba(255,255,255,0.1)" strokeWidth="1" />
        <text x="12" y="22" fontSize="11" fontWeight="600" fill="#e2e8f0">Node Types</text>
        <circle cx="18" cy="42" r="6" fill="#6366f1" />
        <text x="32" y="46" fontSize="10" fill="#94a3b8">Start</text>
        <circle cx="18" cy="62" r="6" fill="#f59e0b" />
        <text x="32" y="66" fontSize="10" fill="#94a3b8">Patient</text>
        <circle cx="18" cy="82" r="6" fill="#10b981" />
        <text x="32" y="86" fontSize="10" fill="#94a3b8">Hospital</text>
        <circle cx="18" cy="102" r="6" fill="#475569" />
        <text x="32" y="106" fontSize="10" fill="#94a3b8">Normal</text>
      </g>
      {/* Traffic Legend */}
      <g transform="translate(830, 20)">
        <rect x="0" y="0" width="150" height="100" fill="rgba(15, 23, 42, 0.9)" rx="8" opacity="0.95" stroke="rgba(255,255,255,0.1)" strokeWidth="1" />
        <text x="12" y="22" fontSize="11" fontWeight="600" fill="#e2e8f0">Traffic Levels</text>
        <line x1="14" y1="40" x2="32" y2="40" stroke="#10b981" strokeWidth="2" />
        <text x="40" y="44" fontSize="10" fill="#94a3b8">Low</text>
        <line x1="14" y1="60" x2="32" y2="60" stroke="#f59e0b" strokeWidth="2" />
        <text x="40" y="64" fontSize="10" fill="#94a3b8">Moderate</text>
        <line x1="14" y1="80" x2="32" y2="80" stroke="#ef4444" strokeWidth="2" />
        <text x="40" y="84" fontSize="10" fill="#94a3b8">Heavy</text>
        <line x1="14" y1="100" x2="32" y2="100" stroke="#6b7280" strokeWidth="2" strokeDasharray="3,3" />
        <text x="40" y="104" fontSize="10" fill="#94a3b8">Blocked</text>
      </g>
    </svg>
  );
};

export default GraphVisualization;
